<?php
require_once dirname(__DIR__) . '/config.php';
if (empty($_SESSION['admin_id'])) { header('Location: login.php'); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $id = filter_input(INPUT_POST, 'booking_id', FILTER_VALIDATE_INT) ?: 0;
    $status = (string)($_POST['status'] ?? '');
    $payment = (string)($_POST['payment_status'] ?? '');
    $allowedStatus = ['pending','confirmed','cancelled','completed'];
    $allowedPayment = ['not_started','pending','paid','failed','refunded'];
    if ($id > 0 && in_array($status, $allowedStatus, true) && in_array($payment, $allowedPayment, true)) {
        $stmt = db()->prepare('UPDATE bookings SET status = ?, payment_status = ? WHERE id = ?');
        $stmt->execute([$status, $payment, $id]);
        header('Location: dashboard.php?updated=1'); exit;
    }
}
$stats = db()->query("SELECT COUNT(*) total, SUM(status='pending') pending, SUM(status='confirmed') confirmed, SUM(payment_status='paid') paid FROM bookings")->fetch();
$bookings = db()->query('SELECT b.*,d.name destination_name FROM bookings b JOIN destinations d ON d.id=b.destination_id ORDER BY b.created_at DESC LIMIT 300')->fetchAll();
$destinations = db()->query('SELECT * FROM destinations ORDER BY created_at DESC')->fetchAll();
?>
<!doctype html><html lang="sw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard — Tembea Tanzania</title><style>
:root{--bg:#f4f5f1;--panel:#fff;--ink:#17251f;--muted:#6d7971;--forest:#173c30;--gold:#d6b77a;--line:#e0e5dd}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Arial,sans-serif;color:var(--ink)}header{background:var(--forest);color:white;padding:18px 24px;display:flex;justify-content:space-between;gap:15px;align-items:center}header a{color:white;text-decoration:none;font-size:13px}.wrap{max-width:1250px;margin:auto;padding:25px 18px}h1{font:500 34px Georgia,serif;margin:5px 0}p{color:var(--muted);font-size:13px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.stat,.panel{background:var(--panel);border:1px solid var(--line);padding:17px;border-radius:8px}.stat strong{display:block;font-size:26px}.stat span{font-size:12px;color:var(--muted)}.panel{margin-top:20px;overflow:hidden}.panel h2{font:500 24px Georgia,serif;margin:0 0 15px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:980px;font-size:12px}th,td{text-align:left;border-bottom:1px solid var(--line);padding:12px 9px;vertical-align:top}th{font-size:10px;text-transform:uppercase;letter-spacing:.7px;color:var(--muted)}input,select{padding:8px;border:1px solid var(--line);background:white;max-width:100%}button{padding:9px 12px;border:0;background:var(--forest);color:white;cursor:pointer;font-size:11px}.inline{display:flex;gap:5px;align-items:center}.tag{display:inline-block;padding:5px 7px;background:#f0eee6;border-radius:4px}.success{background:#e4f6e9;color:#215c32;padding:10px;margin-bottom:12px}.destinations{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.dest img{width:100%;height:120px;object-fit:cover}.dest h3{font-size:15px;margin:10px 0 5px}.dest p{line-height:1.5}.small{font-size:11px}@media(max-width:700px){header{padding:15px;align-items:flex-start}.stats{grid-template-columns:repeat(2,1fr)}.destinations{grid-template-columns:1fr}.wrap{padding:18px 12px}h1{font-size:29px}}
</style></head><body><header><strong>✦ TEMBEA TANZANIA <span style="color:#d6b77a">/ ADMIN</span></strong><div>Habari, <?=e($_SESSION['admin_username']??'Admin')?> · <a href="logout.php">Toka ↗</a></div></header><main class="wrap"><div><p>OVERVIEW / BOOKING MANAGEMENT</p><h1>Dashboard</h1><p>Simamia maombi, status za booking na rekodi za malipo zilizothibitishwa nje ya mfumo.</p></div><?php if(isset($_GET['updated'])):?><div class="success">Mabadiliko yamehifadhiwa.</div><?php endif;?><div class="stats"><div class="stat"><strong><?=(int)$stats['total']?></strong><span>Maombi yote</span></div><div class="stat"><strong><?=(int)$stats['pending']?></strong><span>Yanasubiri</span></div><div class="stat"><strong><?=(int)$stats['confirmed']?></strong><span>Yamethibitishwa</span></div><div class="stat"><strong><?=(int)$stats['paid']?></strong><span>Yamelipwa (rekodi)</span></div></div>
<section class="panel"><h2>Booking enquiries</h2><p class="small">Kuweka payment status kuwa “paid” ni rekodi ya admin tu; hakuthibitishi malipo kutoka gateway yoyote.</p><div class="table-wrap"><table><thead><tr><th>Code / Date</th><th>Customer</th><th>Destination</th><th>Travel</th><th>Guests</th><th>Booking status</th><th>Payment status</th><th>Action</th></tr></thead><tbody><?php if(!$bookings):?><tr><td colspan="8">Bado hakuna maombi ya booking.</td></tr><?php endif;?><?php foreach($bookings as $b):?><tr><td><strong><?=e($b['booking_code'])?></strong><br><span class="small"><?=e($b['created_at'])?></span></td><td><?=e($b['full_name'])?><br><?=e($b['email'])?><br><?=e($b['phone'])?></td><td><?=e($b['destination_name'])?><br><?php if($b['notes']):?><span class="small"><?=e($b['notes'])?></span><?php endif;?></td><td><?=e($b['travel_date'])?></td><td><?=(int)$b['guests']?></td><td><span class="tag"><?=e($b['status'])?></span></td><td><span class="tag"><?=e($b['payment_status'])?></span></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="booking_id" value="<?=(int)$b['id']?>"><div class="inline"><select name="status"><?php foreach(['pending','confirmed','cancelled','completed'] as $s):?><option value="<?=$s?>" <?=$b['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><select name="payment_status"><?php foreach(['not_started','pending','paid','failed','refunded'] as $s):?><option value="<?=$s?>" <?=$b['payment_status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button type="submit">Save</button></div></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Destinations</h2><p>Orodha ya maeneo yaliyowekwa kwenye database. Toleo hili linaonyesha listings; uhariri wa destinations unaweza kuongezwa kama hatua inayofuata.</p><div class="destinations"><?php foreach($destinations as $d):?><article class="dest"><img src="<?=e($d['image_url'])?>" alt="<?=e($d['name'])?>"><h3><?=e($d['name'])?></h3><p><?=e($d['region'])?> · <?=e($d['category'])?><br>From <?=money_tzs($d['price_from'])?></p></article><?php endforeach;?></div></section></main></body></html>
